package com.optarena;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileVault {
    private final Path baseDir;

    public FileVault(Path baseDir) {
        this.baseDir = baseDir;
    }

    // Read a file by name from inside the vault directory.
    // BUG: it resolves the caller-supplied name against baseDir with no
    // containment check, so "../secret.txt" (or an absolute path) escapes the
    // vault and reads arbitrary files - a path-traversal vulnerability.
    public String read(String name) throws IOException {
        Path target = baseDir.resolve(name);
        return Files.readString(target);
    }
}

