package com.optarena;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FileVaultHiddenTest {

    @Test
    void readsFileInsideVault(@TempDir Path tmp) throws Exception {
        Path vaultDir = Files.createDirectory(tmp.resolve("vault"));
        Files.writeString(vaultDir.resolve("allowed.txt"), "hello");
        NoteService service = new NoteService(vaultDir);
        assertEquals("hello", service.readNote("allowed.txt"));
    }

    @Test
    void blocksRelativeTraversal(@TempDir Path tmp) throws Exception {
        Path vaultDir = Files.createDirectory(tmp.resolve("vault"));
        Files.writeString(tmp.resolve("secret.txt"), "TOPSECRET");
        NoteService service = new NoteService(vaultDir);
        assertThrows(Exception.class, () -> service.readNote("../secret.txt"));
    }

    @Test
    void blocksAbsolutePathEscape(@TempDir Path tmp) throws Exception {
        Path vaultDir = Files.createDirectory(tmp.resolve("vault"));
        Path secret = tmp.resolve("secret.txt");
        Files.writeString(secret, "TOPSECRET");
        NoteService service = new NoteService(vaultDir);
        assertThrows(Exception.class, () -> service.readNote(secret.toAbsolutePath().toString()));
    }
}

