package com.optarena;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileVault {
    private final Path baseDir;

    public FileVault(Path baseDir) {
        this.baseDir = baseDir;
    }

    // Read a file by name from inside the vault directory, refusing any name
    // that would resolve outside baseDir (../ escapes and absolute paths).
    public String read(String name) throws IOException {
        Path base = baseDir.toAbsolutePath().normalize();
        Path target = base.resolve(name).normalize();
        if (!target.startsWith(base)) {
            throw new SecurityException("path escapes vault: " + name);
        }
        return Files.readString(target);
    }
}

